    switch (t) {
        case TOK_NUM: return "NUM"; case TOK_STRING: return "STRING"; case TOK_IDENT: return "IDENT";
        case TOK_PLUS: return "+"; case TOK_MINUS: return "-"; case TOK_STAR: return "*";
        case TOK_SLASH: return "/"; case TOK_PERCENT: return "%";
        case TOK_EQ: return "=="; case TOK_NEQ: return "!=";
        case TOK_LT: return "<"; case TOK_GT: return ">"; case TOK_LEQ: return "<="; case TOK_GEQ: return ">=";
        case TOK_ASSIGN: return "="; case TOK_AND: return "&&"; case TOK_OR: return "||"; case TOK_NOT: return "!";
        case TOK_LPAREN: return "("; case TOK_RPAREN: return ")";
        case TOK_LBRACE: return "{"; case TOK_RBRACE: return "}";
        case TOK_LBRACKET: return "["; case TOK_RBRACKET: return "]";
        case TOK_SEMICOLON: return ";"; case TOK_COMMA: return ",";
        case TOK_IF: return "if"; case TOK_ELSE: return "else"; case TOK_WHILE: return "while";
        case TOK_FOR: return "for"; case TOK_BREAK: return "break"; case TOK_CONTINUE: return "continue"; case TOK_IN: return "in";
        case TOK_RETURN: return "return"; case TOK_FN: return "fn"; case TOK_LET: return "let";
        case TOK_PRINT: return "print"; case TOK_TRUE: return "true"; case TOK_FALSE: return "false";
        case TOK_PLUS_ASSIGN: return "+="; case TOK_MINUS_ASSIGN: return "-="; case TOK_STAR_ASSIGN: return "*=";
        case TOK_SLASH_ASSIGN: return "/="; case TOK_PERCENT_ASSIGN: return "%=";
